import{_ as r,o as t,c as o,a2 as s}from"./chunks/framework.gtmkOXzY.js";const m=JSON.parse('{"title":"Performance on busy servers","description":"","frontmatter":{},"headers":[],"relativePath":"ms-flightsim/performance.md","filePath":"ms-flightsim/performance.md","lastUpdated":null}'),n={name:"ms-flightsim/performance.md"};function a(i,e,c,l,d,f){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="performance-on-busy-servers" tabindex="-1">Performance on busy servers <a class="header-anchor" href="#performance-on-busy-servers" aria-label="Permalink to &quot;Performance on busy servers&quot;">​</a></h1><p>The defaults are tuned for high-population servers. The main lever is how many AI aircraft and NPCs exist at once.</p><ul><li><strong>AI traffic</strong> is the biggest cost. Keep <code>Config.AITraffic.groundOnly = true</code> (the default), and use <code>/aitraffic preset light</code> if the airport feels heavy. <code>Config.AITraffic.maxConcurrentCap</code> sets the hard limit.</li><li><strong>Mission NPCs</strong> are created only on the client that needs them, so a crowded LSIA doesn&#39;t hit the entity limit. The settings are in <code>Config.Performance</code>.</li><li><strong>Leftover entities</strong>: job vehicles and props are deleted by the server when their owner disconnects.</li><li><strong>Idle cost</strong>: when nobody is near a screen or flying, the script only runs light background checks. The tower console and ground board draw only while a player is within 30 m.</li><li>Switch off systems you don&#39;t use in <code>Config.Features</code> (for example the floating radar or runway guide) to save a little more.</li></ul>',3)])])}const p=r(n,[["render",a]]);export{m as __pageData,p as default};
